sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var responseBody = {};
    var priority = request.getHeader('priority');
    var tableID = request.getHeader('tableName');


    //gs.info('Scripted API ' + tableID);

    var getData = new GlideRecord(tableID);
    getData.addQuery('priority', priority);
    getData.query();
    while (getData.next()) {

        responseBody.record = getData.number;
        responseBody.short_description = getData.short_description;
    }


    if (getData) {
        //var tableName = getData.sys_class_name.slice(0, 1).toUpperCase() + getData.sys_class_name.toString().slice(1);
       // responseBody.message = tableName + " " + getData.number + ' has been created successfully';


    } else {
        responseBody.message = 'Data pull failed. Please contact administrator';
        responseBody.tableName = tableID;
    }
    response.setBody(JSON.stringify(responseBody));

})(request, response);
